from sqlalchemy.orm import Session
from app.models.action import ClimateAction,UserAction
from app.models.challenge import Challenge,ChallengeAction,UserChallenge
from app.services.challenge_service import calculate_progress
def test_progress_counts_only_owned_completed_actions(db_connection,client):
 uid=client.post('/api/v1/auth/register',json={'name':'Progress User','email':'progress@example.com','password':'correct-horse-battery-staple'}).json()['user']['id'];s=Session(bind=db_connection,join_transaction_mode="create_savepoint");a=list(s.query(ClimateAction).limit(3));c=Challenge(title="Test",slug="test-progress",description="x",active=True);u=UserChallenge(user_id=uid,challenge=c);s.add_all([c,u]);s.flush();s.add_all([ChallengeAction(challenge_id=c.id,action_id=a[0].id),ChallengeAction(challenge_id=c.id,action_id=a[1].id),UserAction(user_id=u.user_id,action_id=a[0].id,status='completed'),UserAction(user_id=u.user_id,action_id=a[1].id,status='started'),UserAction(user_id=u.user_id,action_id=a[2].id,status='completed')]);s.commit();p=calculate_progress(s,u);assert p=={'completed_required_actions':1,'total_required_actions':2,'progress_percent':50.0};s.add(UserAction(user_id=u.user_id,action_id=a[1].id,status='completed'));s.commit();assert calculate_progress(s,u)['progress_percent']==100.0;c2=Challenge(title='Empty',slug='empty-progress',description='x');m=UserChallenge(user_id=u.user_id,challenge=c2);s.add_all([c2,m]);s.commit();assert calculate_progress(s,m)['progress_percent']==0.0
